import React from 'react';
import type {FC} from 'react';

import type {MetaEntityV2} from '@weavix/tracker-api-types';

import {GoalIcon} from '../GoalIcon';
import {KeyResultIcon} from '../KeyResultIcon';
import {PortfolioIcon} from '../PortfolioIcon';
import {ProjectIcon} from '../ProjectIcon';

export type MetaEntityIconProps = {
    entity: Pick<MetaEntityV2, 'entityType' | 'id' | 'shortId'>;
    size?: number;
};

export const MetaEntityIcon: FC<MetaEntityIconProps> = ({entity, size = 20}) => {
    const {entityType, id, shortId} = entity;

    switch (entityType) {
        case 'portfolio':
            return <PortfolioIcon portfolioId={id} size={size} />;
        case 'project':
            return <ProjectIcon projectId={Number(shortId)} size={size} />;
        case 'goal':
            return <GoalIcon goalId={Number(shortId)} size={size} />;
        case 'keyResult' as unknown as MetaEntityV2['entityType']:
            return <KeyResultIcon size={size} />;
        default:
            return null;
    }
};
